param([double]$Hours=8)
$ErrorActionPreference='Stop'; $root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path; $out=Join-Path $root 'tools\asset-gen\out\art-overnight-20260807-revised'; New-Item -ItemType Directory -Force -Path $out | Out-Null
$python=(Get-Command python -ErrorAction Stop).Source; $pidPath=Join-Path $out 'run.pid'; $log=Join-Path $out 'runner.log'
if(Test-Path $pidPath){$old=[int](Get-Content $pidPath -Raw); if(Get-Process -Id $old -ErrorAction SilentlyContinue){Write-Output "Already running PID $old"; exit 0}; Remove-Item $pidPath -Force}
Push-Location $root; try { & $python tools/asset-gen/forge.py status *> $null; if($LASTEXITCODE -ne 0){ & $python tools/asset-gen/forge.py start }; & $python -m py_compile tools/asset-gen/run_art_overnight.py; if($LASTEXITCODE -ne 0){throw 'runner syntax failed'}; $args=@('-u','tools/asset-gen/run_art_overnight.py','--hours',$Hours,'--spec','tools/asset-gen/batches/art_overnight_20260807_revised.json','--prefix','overnight16r_20260807_','--output','tools/asset-gen/out/art-overnight-20260807-revised'); $p=Start-Process -FilePath $python -ArgumentList $args -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput $log -RedirectStandardError (Join-Path $out 'runner.err.log') -PassThru; Set-Content $pidPath $p.Id -Encoding ascii; Write-Output "Started revised campaign PID $($p.Id)" } finally {Pop-Location}
